function initCarousel(){initIndicators(),initEvents(),startSlideTimeout()}function startSlideTimeout(){slideTimeout&&clearTimeout(slideTimeout),slideTimeout=setTimeout(()=>{slideNext()},slideDelay)}function initEvents(){window.addEventListener("resize",function(e){this.clearTimeout(resizeTimeout),goToSlide(getCurrentSlideIndex())}),document.querySelectorAll("[class^=carousel-control]").forEach(e=>{e.addEventListener("click",function(e){const t=e.target.classList;t.contains("carousel-control-prev")?slidePrev():t.contains("carousel-control-next")&&slideNext(),startSlideTimeout()})})}function initIndicators(){const e=document.querySelector(".carousel-indicators"),t=document.querySelectorAll(".carousel-inner .carousel-item");t.forEach((t,o)=>{const i=document.createElement("button");i.classList.add("pointer"),i.ariaLabel=`Slide ${o+1}`,t.classList.contains("active")&&(i.classList.add("active"),i.ariaCurrent=!0),i.addEventListener("click",function(e){goToSlide(o)}),e.appendChild(i)})}function setSelectedIndicator(e){const t=document.querySelectorAll(".carousel-indicators button");t.forEach(e=>{e.classList.remove("active"),e.ariaCurrent=!1}),t[e].classList.add("active"),t[e].ariaCurrent=!0}function slidePrev(){const e=document.querySelectorAll(".carousel-item"),t=document.querySelector(".carousel-item.active");if(!t)return;const o=Array.from(e).indexOf(t),i=(o-1+e.length)%e.length;goToSlide(i)}function slideNext(){const e=document.querySelectorAll(".carousel-item"),t=document.querySelector(".carousel-item.active");if(!t)return;const o=Array.from(e).indexOf(t),i=(o+1)%e.length;goToSlide(i)}function goToSlide(e){const t=document.querySelector(".carousel-inner"),o=document.querySelectorAll(".carousel-item");if(!t||0===o.length||e<0||e>=o.length)return;const i=document.querySelector(".carousel-item.active");i&&i.classList.remove("active");const n=o[e];n.classList.add("active");const c=e*n.clientWidth;t.scrollTo({left:c}),setSelectedIndicator(e),startSlideTimeout()}function getCurrentSlideIndex(){const e=document.querySelectorAll(".carousel-item"),t=document.querySelector(".carousel-item.active"),o=Array.from(e).indexOf(t);return o}const slideDelay=3e3;let slideTimeout=null,resizeTimeout=null;document.addEventListener("DOMContentLoaded",function(e){initCarousel()});